def get_future_main_code(code):
    if code.split('.')[1] not in ('CCFX', 'XDCE', 'XSGE', 'XZCE'):
        strategy_log.warning('请输入正确的期货代码')
        return ''
    else:
        future_code_dict = engine_instance().data_proxy.get_underlying_code(code)
        if len(future_code_dict[code]) == 0:
            strategy_log.warning('获取主力合约为空，请检查输入代码')
            return ''
        else:
            return future_code_dict[code][1]
